import math
L1=2.75; A=1.05; L2=2.6
phase='rev'
af=0.0
lastp=-10
def clamp(x,a,b):
    return max(a,min(b,x))
def deq(phid):
    p=math.radians(phid)
    return math.degrees(math.atan(L1*math.sin(p)/(L2+A*math.cos(p))))
def control(obs):
    global phase,af,lastp
    t=obs['t']
    rig=obs['rig']; H=rig['hitch']; R=rig['trailer_rear']; phi=obs['hitch_deg']
    look=-23
    if phase=='rev' and abs(phi)>45:
        phase='fwd'; wake('hitch %.0f, pulling forward'%phi)
    if phase=='fwd':
        if abs(phi)<8:
            phase='rev'
        else:
            return (0.0, 1.0, look)
    ux=R[0]-H[0]; uy=R[1]-H[1]; n=math.hypot(ux,uy) or 1.0
    th0=math.atan2(uy,ux)
    pts=[]
    for v in (obs.get('views') or {}).values():
        ox,oy=v['origin']
        for b,d in v.get('walls',[]):
            px=ox+d*math.cos(math.radians(b)); py=oy+d*math.sin(math.radians(b))
            rx=px-R[0]; ry=py-R[1]
            if math.hypot(rx,ry)<10: pts.append((rx,ry))
    margin=rig['trailer_half_width']+0.3
    best=None; besta=0.0
    for a in range(-70,71,5):
        th=th0+math.radians(a); dx=math.cos(th); dy=math.sin(th)
        clear=9.0
        for rx,ry in pts:
            al=rx*dx+ry*dy
            cr=dx*ry-dy*rx
            if al>0 and abs(cr)<margin and al<clear: clear=al
        sc=min(clear,8.0)-0.02*abs(a)-0.01*abs(a-af)
        if best is None or sc>best:
            best=sc; besta=float(a)
    dx=math.cos(th0); dy=math.sin(th0)
    dccw=3.0; dcw=3.0
    for rx,ry in pts:
        al=rx*dx+ry*dy; cr=dx*ry-dy*rx
        if -1.0<al<3.0:
            if cr>0: dccw=min(dccw,cr)
            else: dcw=min(dcw,-cr)
    a=besta+clamp(8.0*(dccw-dcw),-10,10)
    tg=obs.get('target') or {}
    used_t=False
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        e=rig['eye']; b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        gx=e[0]+d*math.cos(b)-R[0]; gy=e[1]+d*math.sin(b)-R[1]
        dist=math.hypot(gx,gy)
        if dist<9:
            used_t=True
            if dist<2.0: a=0.0
            else:
                ga=math.degrees(math.atan2(gy,gx)-th0)
                ga=(ga+180)%360-180
                a=ga
    af=0.6*af+0.4*a
    phid=clamp(-1.0*af,-38,38)
    st=deq(phid)+2.0*(phi-phid)
    st=clamp(st,-34,34)
    sp=-0.9
    if t-lastp>2:
        lastp=t
        print('t%.1f phi%.1f a%.1f af%.1f phid%.1f st%.1f np%d tgt%s'%(t,phi,besta,af,phid,st,len(pts),used_t))
    return (st, sp, look)

