import math
X=0.0;Y=0.0;PSI=0.0
grid={}
DES=None
G=[140,64,-64,-140,-64,64]
gi=0;dwell=0
mode='rev'
fdist=0.0
flim=4.5
lastp=-10

def wrap(a):
    return (a+180.0)%360.0-180.0

def clamp(v,a,b):
    return max(a,min(b,v))

def ff(phi):
    p=math.radians(phi)
    return math.degrees(math.atan(2.5*math.sin(p)/(3.6+1.3*math.cos(p))))

def mid_at(pts,c,s,L,w):
    dl=None;dr=None
    for dx,dy in pts:
        al=dx*c+dy*s
        if al<L-w or al>L+w: continue
        l=-dx*s+dy*c
        if 0<l<5.0 and (dl is None or l<dl): dl=l
        if -5.0<l<0 and (dr is None or -l<dr): dr=-l
    if dl is not None and dr is not None: return (dl-dr)/2.0,dl,dr
    if dl is not None: return clamp(dl-2.8,-2.5,2.5),dl,dr
    if dr is not None: return clamp(2.8-dr,-2.5,2.5),dl,dr
    return None,dl,dr

def control(obs):
    global X,Y,PSI,DES,gi,dwell,mode,fdist,flim,lastp
    dt=obs.get('dt',0.1) or 0.1
    m=obs['motion']; v=m['v_mps']; st=obs['steer_deg']
    PSI+=math.degrees(v*math.tan(math.radians(st))/2.5*dt)
    pr=math.radians(PSI)
    X+=v*math.cos(pr)*dt; Y+=v*math.sin(pr)*dt
    c0=math.cos(pr); s0=math.sin(pr)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        ox,oy=vw['origin']
        for w in vw.get('walls',[]):
            b,d=w[0],w[1]
            if d>14: continue
            vx=ox+d*math.cos(math.radians(b)); vy=oy+d*math.sin(math.radians(b))
            wx=X+vx*c0-vy*s0; wy=Y+vx*s0+vy*c0
            grid[(round(wx/0.3),round(wy/0.3))]=(wx,wy)
    h=obs['head']
    if abs(h['gaze_deg']-G[gi])<2 and views:
        dwell+=1
        if dwell>=3:
            gi=(gi+1)%len(G); dwell=0
    look=G[gi]
    phi=obs['hitch_deg']
    rig=obs['rig']
    rx,ry=rig['trailer_rear']
    Px=X+rx*c0-ry*s0; Py=Y+rx*s0+ry*c0
    back=PSI+rig['trailer_heading_deg']+180.0
    status=obs.get('status')
    t=obs['clock']['t']
    if status=='JACKKNIFED' or abs(phi)>45:
        if mode!='fwd': fdist=0.0; flim=3.5
        mode='fwd'
    if mode=='fwd':
        if v>0: fdist+=v*dt
        if fdist>flim or abs(phi)<5:
            mode='rev'
        else:
            if v<-0.05: return (st,0.0,look)
            return (clamp(-0.8*phi,-30,30) if False else 0.0,1.2,look)
    if v>0.05:
        return (0.0,-0.8,look)
    pts=[]
    for (wx,wy) in grid.values():
        dx=wx-Px; dy=wy-Py
        if dx*dx+dy*dy<144: pts.append((dx,dy))
    a_=math.radians(back); c=math.cos(a_); s=math.sin(a_)
    m0,dl0,dr0=mid_at(pts,c,s,0.3,1.3)
    m3,_,_=mid_at(pts,c,s,3.0,1.5)
    m6,_,_=mid_at(pts,c,s,6.5,2.0)
    angs=[]
    if m3 is not None: angs.append(math.degrees(math.atan2(m3,3.0)))
    if m6 is not None: angs.append(0.6*math.degrees(math.atan2(m6,6.5)))
    la=sum(angs)/len(angs) if angs else 0.0
    if m0 is not None:
        thc=0.65*clamp(15.0*m0,-30,30)+0.35*la
        if dl0 is not None and dl0<1.7: thc=min(thc,-8.0)
        if dr0 is not None and dr0<1.7: thc=max(thc,8.0)
    else:
        thc=la
    thc=clamp(thc,-35,35)
    desw=back+thc
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        ex,ey=rig['eye']
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        vx=ex+d*math.cos(b); vy=ey+d*math.sin(b)
        tx=X+vx*c0-vy*s0; ty=Y+vx*s0+vy*c0
        dd=math.hypot(tx-Px,ty-Py)
        if dd>3.0:
            ang=math.degrees(math.atan2(ty-Py,tx-Px))
            if abs(wrap(ang-back))<50:
                desw=desw+0.4*wrap(ang-desw)
    if DES is None: DES=desw
    DES=DES+0.3*wrap(desw-DES)
    e=wrap(DES-back)
    phid=-clamp(1.0*e,-25,25)
    steer=clamp(ff(phi)+3.0*(phi-phid),-45,45)
    sp=-0.8
    if (dl0 is not None and dl0<1.8) or (dr0 is not None and dr0<1.8): sp=-0.5
    if t-lastp>3:
        lastp=t
        print('t%.0f phi%.0f e%.0f thc%.0f m0%s dl%s dr%s m3%s m6%s prog%s'%(t,phi,e,thc,None if m0 is None else round(m0,1),None if dl0 is None else round(dl0,1),None if dr0 is None else round(dr0,1),None if m3 is None else round(m3,1),None if m6 is None else round(m6,1),obs['progress'].get('covered')))
    return (steer,sp,look)

