import math
mode='fwd0'
fd=0.0
n=0
last_err=0.0
def ang(x,y):
    return math.degrees(math.atan2(y,-x))
def control(obs):
    global mode,fd,n,last_err
    n+=1
    dt=obs.get('dt',0.1)
    h=obs['hitch_deg']; rig=obs['rig']
    hx,hy=rig['hitch']; rx,ry=rig['trailer_rear']
    v=obs['motion']['v_mps']
    look=170
    if mode=='fwd0':
        fd+=max(0.0,v)*dt
        if fd>1.3:
            mode='rev'
        return (0.0,0.7,look)
    if mode=='fwd':
        if abs(h)<5: mode='rev'
        return (0.0,0.8,look)
    if abs(h)>35:
        mode='fwd'; return (0.0,0.8,look)
    dx=rx-hx; dy=ry-hy
    sl=dy/dx if abs(dx)>1e-6 else 0.0
    ax=rx-1.5
    L=[];R=[]
    views=obs.get('views') or {}
    corners=[]
    for k in ('direct','periphery'):
        vw=views.get(k)
        if not vw: continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]):
            x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
            if x>hx or x<ax-1.2 or x>ax+1.6: continue
            yl=hy+(x-hx)*sl
            if y>yl: L.append(y)
            else: R.append(y)
        for c in vw.get('target_corners',[]) or []:
            try:
                b,d=c[0],c[1]
                corners.append((ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b))))
            except Exception: pass
    aim=None
    tg=obs.get('target') or {}
    rem=obs['progress']['remaining']
    if len(corners)>=4:
        aim=(sum(c[0] for c in corners)/len(corners),sum(c[1] for c in corners)/len(corners))
    elif tg.get('in_sight') and tg.get('bearing_deg') is not None and rem<6:
        ex,ey=rig['eye']; b=tg['bearing_deg']; d=tg['dist_m']
        aim=(ex+d*math.cos(math.radians(b)),ey+d*math.sin(math.radians(b)))
    if aim is None:
        if L and R: c=(min(L)+max(R))/2
        elif L: c=min(L)-0.95
        elif R: c=max(R)+0.95
        else: c=None
        if c is not None:
            aim=(ax,c)
    if aim is not None and aim[0]<rx-0.2:
        err=ang(aim[0]-hx,aim[1]-hy)-ang(dx,dy)
        last_err=err
    elif aim is not None:
        err=0.0
    else:
        err=last_err*0.9; last_err=err
    hdes=max(-22,min(22,1.6*err))
    steer=max(-45,min(45,3.0*(h-hdes)))
    if n%20==0: print('t',round(obs['t'],1),'L',round(min(L),2) if L else None,'R',round(max(R),2) if R else None,'err',round(err,1),'h',round(h,1),'hdes',round(hdes,1),'rem',round(rem,1),'nc',len(corners))
    return (steer,-0.45,look)

