        except Exception: pass
    if mode=='fwd':
        fdist+=abs(v)*dt
        if abs(hitch)<12 or fdist>10:
            mode='rev'
        else:
            return (cl(-1.5*hitch,-42,42),1.5,-41)
    rx,ry=rig['trailer_rear']
    phi=rig['trailer_heading_deg']+180.0
    q=[]
    for (wx,wy) in pts.values():
        dx=wx-X; dy=wy-Y
        px=c*dx+s*dy-rx; py=-s*dx+c*dy-ry
