    if n%30==0:
        print('t%.0f a%.0f hd%.0f h%.0f st%.0f L%.1f R%.1f td%s np%d'%(obs['t'],a,hd_f,hitch,steer,L,R,('%.1f'%tdist) if tdist else '-',len(q)))
    return (steer,sp,-41)

