    D={k:9.0 for k in C}
    for (wx,wy) in pts.values():
        dx=wx-X; dy=wy-Y
        vx=c*dx+s*dy; vy=-s*dx+c*dy
        for k,(cx,cy) in C.items():
            dd=math.hypot(vx-cx,vy-cy)
            if dd<D[k]: D[k]=dd
    hitch=obs['hitch_deg']
    if n%10==0 and phase=='fwd':
        print('t%.0f fd%.1f h%.0f '%(obs['t'],fd,hitch)+' '.join('%s%.2f'%(k,D[k]) for k in sorted(D)))
    if halt:
        return (obs['steer_deg'],0.0,-41)
    if phase=='fwd':
        fd+=abs(v)*dt
        if n>5 and min(D['VL'],D['VR'])<0.35:
            halt=True
            try: wake('front corner near rail '+' '.join('%s%.2f'%(k,D[k]) for k in sorted(D)))
            except Exception: pass
            return (0.0,0.0,0)
        if fd>=2.5:
            phase='scan'
        else:
            return (0.0,0.5,0)
    if phase=='scan':
        if gi>=len(seq) or n>400:
            phase='done'
            print('rig hitch',rig['hitch'],'rear',rig['trailer_rear'],'h%.1f'%hitch,'fd%.2f'%fd)
            print('corners '+' '.join('%s%.2f'%(k,D[k]) for k in sorted(D)))
            print(' '.join('%g,%g'%p for p in sorted(scan.keys())))
            try: wake('scan done')
            except Exception: pass
            return (0.0,0.0,-41)
        g=seq[gi]
        hd=obs['head']
        if abs(v)<0.02 and hd.get('settled') and abs(hd['gaze_deg']-g)<3 and views:
            gk+=1
            if gk>=3: gi+=1; gk=0
        return (0.0,0.0,g)
    return (0.0,0.0,-41)
